import type { FoodItem } from '@motivation/shared';

type Unit = Pick<FoodItem, 'base_unit' | 'serving_quantity'>;

/**
 * Story 435 — what the replace confirm starts "1 <from unit> is … <to unit>" at, when the units
 * differ: g ↔ ml one to one (the app-wide food approximation), and a piece the grams per piece the
 * piece-side food declares (`serving_quantity`, as `amountInItemUnits` reads it). Null when the
 * units match, or when nothing says.
 */
export function suggestedFactor(from: Unit, to: Unit): number | null {
    if (from.base_unit === to.base_unit) return null;
    if (from.base_unit !== 'piece' && to.base_unit !== 'piece') return 1;
    if (from.base_unit === 'piece') return from.serving_quantity ?? null;
    return to.serving_quantity ? 1 / to.serving_quantity : null;
}
