import { nowTimestamp, type FoodItem, type NewFoodItem } from '@motivation/shared';
import { HealthService } from '../../../services/health.service.js';
import { goBack, navigate } from '../../../router.js';
import { buildSectionPage } from '../../../utils/section-page.utils.js';
import { documentStyleSheet } from '../../../utils/css.js';
import { createComponentLogger } from '../../../utils/component-logger.js';
import { safeExec } from '../../../utils/safe-exec.js';
import type { ScreenComponent } from '../../../types/screen-component.js';
import { createScreenStatusNodes, createScreenStatusMixin } from '../../_shared/screen-status.js';
import {
    HEALTH_EVENTS,
    type FoodEditorArchiveEvent,
    type FoodEditorBarcodeAddEvent,
    type FoodEditorBarcodeRemoveEvent,
    type FoodEditorDeleteEvent,
    type FoodEditorLooksRightEvent,
    type FoodEditorReplaceEvent,
    type FoodEditorSaveEvent,
    type LinePickedEvent,
} from '../health-events.js';
import { suggestedFactor } from '../../../utils/replace-factor.js';
import type { LineView } from '../../../utils/line-view.js';
import '../nutrition/food-editor/food-editor.component.js';
import '../nutrition/line-add-dialog/line-add-dialog.component.js';
import type { FoodEditor } from '../nutrition/food-editor/food-editor.component.js';
import type { LineAddDialog } from '../nutrition/line-add-dialog/line-add-dialog.component.js';
import themeStyles from '../health-theme.css?inline';

documentStyleSheet(themeStyles);

/** What "+ New food" starts from: a manual food per 100 g. */
export function blankFood(name = ''): NewFoodItem {
    return { canonical_name: name, display_name: name, source: 'manual', base_amount: 100, base_unit: 'g' };
}

/**
 * Story 423 — one food of the library: `/health/foods/:id` edits it (with its barcodes, Archive
 * and Delete), `/health/foods/new` makes one (`?name=` prefills). `<food-editor>` emits; this writes.
 */
export class HealthFoodEditScreen extends HTMLElement implements ScreenComponent {
    private initialized = false;
    private idValue: string | null = null;
    private nameValue = '';
    private readonly host = document.createElement('div');
    private readonly log = createComponentLogger('health-food-edit-screen');
    private statusNodes = createScreenStatusNodes();
    private statusMixin = createScreenStatusMixin(this.statusNodes.loadingNode, this.statusNodes.errorNode, this.statusNodes.retryNode);

    setLoading(): void { this.statusMixin.setLoading(); }
    setError(err: unknown): void { this.statusMixin.setError(err); }
    clearStatus(): void { this.statusMixin.clearStatus(); }

    /** The food to edit; null for a new one. */
    set foodId(value: string | null) { this.idValue = value; }
    set query(value: URLSearchParams) { this.nameValue = value.get('name') ?? ''; }

    connectedCallback(): void {
        if (this.initialized) return;
        this.initialized = true;
        const page = buildSectionPage(this, this.idValue ? 'Edit food' : 'New food', 'health', '/health/foods');
        this.statusNodes.retryNode.addEventListener('click', () => void this.load());
        page.content.append(this.statusNodes.loadingNode, this.statusNodes.errorNode, this.statusNodes.retryNode, this.host);
        void this.load();
    }

    private async load(): Promise<void> {
        return safeExec(this, this.log, async () => {
            if (!this.idValue) {
                this.renderNew();
                return;
            }
            const food = await HealthService.findFoodItem(this.idValue);
            if (!food) throw new Error(`Food ${this.idValue} not found.`);
            this.renderEdit(food, await HealthService.getFoodItemBarcodes(food.id));
        });
    }

    private editor(mode: 'edit' | 'new'): FoodEditor {
        const editor = document.createElement('food-editor') as FoodEditor;
        editor.setAttribute('mode', mode);
        customElements.upgrade(editor);
        this.host.replaceChildren(editor);
        return editor;
    }

    private renderNew(): void {
        const editor = this.editor('new');
        editor.food = blankFood(this.nameValue);
        editor.addEventListener(HEALTH_EVENTS.FOOD_EDITOR_SAVE, (e: FoodEditorSaveEvent) => {
            e.detail.respondWith = safeExec(this, this.log, async () => {
                const created = await HealthService.createFoodItem(e.detail.food);
                // The new food's own page, in place of the blank one: Back is the library.
                navigate(`/health/foods/${encodeURIComponent(created.id)}`, { history: 'replace' });
            });
        });
    }

    private renderEdit(food: FoodItem, barcodes: Awaited<ReturnType<typeof HealthService.getFoodItemBarcodes>>): void {
        const editor = this.editor('edit');
        editor.food = food;
        editor.barcodes = barcodes;
        const refreshBarcodes = async () => { editor.barcodes = await HealthService.getFoodItemBarcodes(food.id); };

        editor.addEventListener(HEALTH_EVENTS.FOOD_EDITOR_SAVE, (e: FoodEditorSaveEvent) => {
            e.detail.respondWith = safeExec(this, this.log, async () => {
                await HealthService.updateFoodItem(food.id, e.detail.food);
                goBack('/health/foods');
            });
        });
        editor.addEventListener(HEALTH_EVENTS.FOOD_EDITOR_ARCHIVE, (e: FoodEditorArchiveEvent) => {
            e.detail.respondWith = safeExec(this, this.log, async () => {
                editor.food = await HealthService.updateFoodItem(food.id, { archived_at: e.detail.archived ? nowTimestamp() : null });
            });
        });
        editor.addEventListener(HEALTH_EVENTS.FOOD_EDITOR_DELETE, (e: FoodEditorDeleteEvent) => {
            e.detail.respondWith = safeExec(this, this.log, async () => {
                const meals = await HealthService.getMealsUsingFood(food.id);
                if (!(await editor.confirmDelete(meals))) return;
                await HealthService.deleteFoodItem(food.id);
                goBack('/health/foods');
            });
        });
        if (food.source === 'ai_estimate') this.wireCheck(editor, food);
        editor.addEventListener(HEALTH_EVENTS.FOOD_EDITOR_BARCODE_ADD, (e: FoodEditorBarcodeAddEvent) => {
            e.detail.respondWith = safeExec(this, this.log, async () => {
                await HealthService.mapFoodItemBarcode(food.id, e.detail.barcode);
                await refreshBarcodes();
            });
        });
        editor.addEventListener(HEALTH_EVENTS.FOOD_EDITOR_BARCODE_REMOVE, (e: FoodEditorBarcodeRemoveEvent) => {
            e.detail.respondWith = safeExec(this, this.log, async () => {
                await HealthService.removeFoodItemBarcode(food.id, e.detail.barcode);
                await refreshBarcodes();
            });
        });
    }

    /**
     * Story 435 — an AI-made food is checked ("Looks right") or replaced: by a food picked in the
     * sheet (library or Open Food Facts, no meals) or a label read under its name. The confirm comes
     * before a new food is added, so Cancel leaves the library as it was.
     */
    private wireCheck(editor: FoodEditor, food: FoodItem): void {
        const sheet = document.createElement('line-add-dialog') as LineAddDialog;
        sheet.setAttribute('heading', 'Replace with…');
        sheet.setAttribute('actions', 'scan');
        sheet.setAttribute('no-meals', '');
        this.host.append(sheet);

        editor.addEventListener(HEALTH_EVENTS.FOOD_EDITOR_LOOKS_RIGHT, (e: FoodEditorLooksRightEvent) => {
            e.detail.respondWith = safeExec(this, this.log, async () => {
                editor.food = await HealthService.updateFoodItem(food.id, { reviewed_at: nowTimestamp() });
            });
        });
        editor.addEventListener(HEALTH_EVENTS.FOOD_EDITOR_REPLACE, (e: FoodEditorReplaceEvent) => {
            if (e.detail.with === 'label') sheet.readLabelAs(food.display_name, e.detail.source);
            else sheet.open(null);
        });
        sheet.addEventListener(HEALTH_EVENTS.LINE_PICKED, (e: LinePickedEvent) => {
            e.stopPropagation();
            void safeExec(this, this.log, () => this.replaceFood(editor, food, e.detail.line, e.detail.bind ?? null));
        });
    }

    // Not `replaceWith`: that name is the DOM's own `Element.replaceWith` (story 438).
    private async replaceFood(editor: FoodEditor, food: FoodItem, line: LineView, bind: string | null): Promise<void> {
        const target = await replacementTarget(line);
        const impact = await HealthService.getFoodReplacement(food.id);
        const answer = await editor.confirmReplace(
            { name: target.food.display_name, unit: target.food.base_unit },
            impact,
            suggestedFactor(food, { base_unit: target.food.base_unit, serving_quantity: target.food.serving_quantity ?? null }),
        );
        if (!answer) return;
        const toId = target.id ?? (await HealthService.createFoodItem(target.food)).id;
        await HealthService.replaceFoodItem(food.id, toId, answer.factor);
        // A scanned code nothing knew, picked for this food (story 432): it is the replacement's now.
        if (bind) await HealthService.mapFoodItemBarcode(toId, bind);
        goBack('/health/foods');
    }
}

/**
 * What a sheet pick replaces with: a library food, or a new one to add — unless it is an Open Food
 * Facts product whose barcode the library already has (an item-code suggestion is not the product).
 */
async function replacementTarget(line: LineView): Promise<{ id: string; food: FoodItem } | { id?: undefined; food: NewFoodItem }> {
    if ('food_item_id' in line.source) {
        const id = line.source.food_item_id;
        const food = await HealthService.findFoodItem(id);
        if (!food) throw new Error(`Food ${id} not found.`);
        return { id, food };
    }
    if ('new_food_item' in line.source) {
        const food = line.source.new_food_item;
        const known = food.barcode ? await HealthService.findFoodItemByBarcode(food.barcode) : null;
        return known && !known.matched_by ? { id: known.id, food: known } : { food };
    }
    throw new Error('A logged line cannot replace a food.');
}

if (!customElements.get('health-food-edit-screen')) {
    customElements.define('health-food-edit-screen', HealthFoodEditScreen);
}
